sql.where:
deleted_at IS NULL
AND id = #{q.id}
AND task_name LIKE CONCAT('%', #{q.keyword}, '%')
AND status = #{q.status}

mapper.select:
SELECT 
FROM group_creation_marketing_item
WHERE status = 1
  AND next_run_at <= #{now}
ORDER BY next_run_at ASC, id ASC
LIMIT #{limit}

mapper.update:
UPDATE group_creation_marketing_item i
JOIN group_creation_marketing_task t ON t.id = i.task_id
SET i.status = #{toStatus},
    i.started_at = COALESCE(i.started_at, #{now}),
    i.updated_at = #{now},
    t.status = CASE WHEN t.status = 1 THEN 2 ELSE t.status END,
    t.updated_at = #{now}
WHERE i.id = #{id}
  AND i.status = #{fromStatus}

UPDATE group_creation_marketing_task
SET marketing_task_id = #{marketingTaskId},
    updated_at = #{updatedAt}
WHERE id = #{taskId}
  AND deleted_at IS NULL
  AND marketing_task_id IS NULL
